create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, nickname text, interests text[], created_at timestamptz not null default now());
create table public.characters (id text primary key, name text not null, public_bio text, active boolean not null default true, created_at timestamptz not null default now());
create table public.story_chapters (id text primary key, character_id text not null references public.characters(id), day smallint not null, title text not null, sort_order smallint not null unique);
create table public.story_events (id text primary key, chapter_id text not null references public.story_chapters(id) on delete cascade, body text not null, conditions jsonb not null default '{}', consequences jsonb not null default '{}');
create table public.story_choices (id text primary key, event_id text not null references public.story_events(id) on delete cascade, text text not null, conditions jsonb not null default '{}', consequences jsonb not null default '{}', next_event_id text);
create table public.conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, character_id text not null default 'luma', summary text, created_at timestamptz not null default now());
create table public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('user','assistant','system')), content text not null, created_at timestamptz not null default now());
create table public.memories (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, character_id text not null default 'luma', title text not null, content text not null, importance smallint not null check(importance between 1 and 10), source_message_id uuid references public.messages(id) on delete set null, discovered boolean not null default false, chapter int not null default 1, created_at timestamptz not null default now());
create table public.relationship_states (user_id uuid primary key references auth.users(id) on delete cascade, trust smallint not null default 10, attachment smallint not null default 5, curiosity smallint not null default 20, fear smallint not null default 15, suspicion smallint not null default 8, familiarity smallint not null default 0, updated_at timestamptz not null default now());
create table public.story_progress (user_id uuid primary key references auth.users(id) on delete cascade, day smallint not null default 1, current_event text not null default 'first-night', flags jsonb not null default '{}', updated_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, type text not null, title text not null, body text not null, metadata jsonb not null default '{}', read boolean not null default false, scheduled_for timestamptz, sent_at timestamptz, created_at timestamptz not null default now());
create table public.notification_preferences (user_id uuid primary key references auth.users(id) on delete cascade, push_enabled boolean not null default false, quiet_hours_start time, quiet_hours_end time, luma_messages boolean not null default true, story_events boolean not null default true, updated_at timestamptz not null default now());
create table public.push_tokens (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, token text not null unique, platform text not null default 'web', created_at timestamptz not null default now(), last_seen_at timestamptz not null default now());
create table public.plans (id text primary key, name text not null, price_kobo integer not null, interval text not null check(interval in ('monthly','yearly')), features jsonb not null default '[]', active boolean not null default true);
create table public.subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, plan_id text references public.plans(id), provider text not null default 'paystack', provider_subscription_code text unique, status text not null check(status in ('active','trialing','past_due','cancelled','expired')), current_period_end timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.payments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subscription_id uuid references public.subscriptions(id) on delete set null, provider_reference text not null unique, amount_kobo integer not null, currency text not null default 'NGN', status text not null check(status in ('pending','success','failed','reversed')), payload jsonb not null default '{}', created_at timestamptz not null default now());
create index messages_conversation_created on public.messages(conversation_id,created_at); create index memories_user_discovered on public.memories(user_id,discovered); create index notifications_user_unread on public.notifications(user_id,read);
create index subscriptions_user_status on public.subscriptions(user_id,status); create index payments_user_created on public.payments(user_id,created_at);
alter table public.profiles enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.memories enable row level security; alter table public.relationship_states enable row level security; alter table public.story_progress enable row level security; alter table public.notifications enable row level security;
alter table public.characters enable row level security; alter table public.story_chapters enable row level security; alter table public.story_events enable row level security; alter table public.story_choices enable row level security;
alter table public.notification_preferences enable row level security; alter table public.push_tokens enable row level security; alter table public.plans enable row level security; alter table public.subscriptions enable row level security; alter table public.payments enable row level security;
create policy "own profiles" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid()); create policy "own conversations" on public.conversations for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own messages" on public.messages for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own memories" on public.memories for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own relationship" on public.relationship_states for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own progress" on public.story_progress for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own notifications" on public.notifications for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "read active characters" on public.characters for select using (active=true); create policy "read story chapters" on public.story_chapters for select using (true); create policy "read story events" on public.story_events for select using (true); create policy "read story choices" on public.story_choices for select using (true);
create policy "own notification preferences" on public.notification_preferences for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own push tokens" on public.push_tokens for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "visible active plans" on public.plans for select using (active=true); create policy "own subscriptions" on public.subscriptions for select using (user_id=auth.uid()); create policy "own payments" on public.payments for select using (user_id=auth.uid());
insert into public.plans(id,name,price_kobo,interval,features) values ('afterdark-monthly','Afterdark',250000,'monthly','["Unlimited conversations","Enhanced memory","Premium branches"]') on conflict do nothing;
